// Parse the chat message to extract the related Jira story key and the raw bug description.
// Expected format: "KAN-1: promo code field does not trim leading spaces..."
const input = $json.chatInput || '';

const keyMatch = input.match(/\b([A-Z][A-Z0-9]+-\d+)\b/);
const storyKey = keyMatch ? keyMatch[1] : null;
const projectKey = storyKey ? storyKey.split('-')[0] : null;

let rawBugDescription = input;
if (keyMatch) {
  rawBugDescription = input.replace(keyMatch[0], '').replace(/^[:\-\s]+/, '').trim();
}

return [{
  json: {
    storyKey,
    projectKey,
    rawBugDescription
  }
}];

// Build a broad JQL pull of recent bugs in this project (no text pre-filtering).
// Duplicate detection is done by the AI agent against the actual candidate list below,
// not by JQL keyword matching (JQL "text ~" does a strict quoted-phrase match, which is
// too brittle to reliably catch semantic duplicates worded differently).
const story = $input.item.json;
const parsed = $('Parse Story Key & Bug Text').item.json;

const projectKey = parsed.projectKey || (story.key ? story.key.split('-')[0] : null);

let duplicateJql = 'issuetype = Bug';
if (projectKey) duplicateJql += ` AND project = ${projectKey}`;
duplicateJql += ' ORDER BY created DESC';

return [{
  json: {
    storyKey: parsed.storyKey,
    projectKey,
    rawBugDescription: parsed.rawBugDescription,
    storySummary: story.Summary || story.summary || '',
    storyDescription: story.Description || story.description || '',
    duplicateJql
  }
}];

// Collapse the duplicate search results into one readable block + structured list,
// including a description excerpt so the AI can compare actual symptoms, not just titles.
// Filter out any placeholder item (from "Always Output Data" firing on zero matches).
const items = $input.all().filter(it => it.json && (it.json.key || it.json.id));
const ctx = $('Extract Search Keywords & Build JQL').first().json;

// Handles Atlassian Document Format (ADF) descriptions, which Jira Cloud returns
// when simplifyOutput isn't actually flattening the response.
function adfToText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  let text = '';
  if (node.type === 'text' && node.text) {
    text += node.text;
  }
  if (Array.isArray(node.content)) {
    for (const child of node.content) {
      text += adfToText(child);
      if (child.type === 'paragraph' || child.type === 'listItem' || child.type === 'heading') {
        text += ' ';
      }
    }
  }
  return text;
}

function excerpt(desc) {
  if (!desc) return '';
  let text;
  if (typeof desc === 'string') {
    text = desc;
  } else if (typeof desc === 'object') {
    text = adfToText(desc);
  } else {
    text = String(desc);
  }
  const clean = text.replace(/\*/g, '').replace(/\n+/g, ' ').trim();
  return clean.length > 300 ? clean.slice(0, 300) + '...' : clean;
}

let candidatesText = '(No existing bugs found in this project to compare against)';
const candidates = [];
if (items.length > 0) {
  candidatesText = items.map(it => {
    const j = it.json;
    const f = j.fields || {};
    const key = j.key || j.id || 'UNKNOWN';
    // Try simplified shape first (Summary/Status/Description), then fall back to raw shape (fields.*)
    const summary = j.Summary ?? j.summary ?? f.summary ?? '(no summary)';
    const status = j.Status ?? j.status ?? f.status?.name ?? '';
    const rawDescription = j.Description ?? j.description ?? f.description ?? '';
    const description = excerpt(rawDescription);
    candidates.push({ key, summary, status, description });
    return `${key}: ${summary} [${status}]\n   ${description}`;
  }).join('\n\n');
}

return [{
  json: {
    ...ctx,
    duplicateCandidatesText: candidatesText,
    duplicateCandidates: candidates,
    topDuplicateKey: candidates.length ? candidates[0].key : ''
  }
}];

const bug = $input.item.json.output;
const dupCtx = $('Format Duplicate Candidates').first().json;
const storyKey = dupCtx.storyKey;

let revisionCount = 0;
try {
  const prevCtx = $('Prepare Revision Context').first();
  if (prevCtx && prevCtx.json && typeof prevCtx.json.revisionCount === 'number') {
    revisionCount = prevCtx.json.revisionCount;
  }
} catch (e) {
  revisionCount = 0;
}
const maxRevisions = 3;

let description = `*Steps to Reproduce:*\n${bug.stepsToReproduce}\n\n`;
description += `*Expected Result:*\n${bug.expectedResult}\n\n`;
description += `*Actual Result:*\n${bug.actualResult}\n\n`;
description += `*Severity:* ${bug.severity} - ${bug.severityJustification}\n\n`;
if (storyKey) description += `*Related Story:* ${storyKey}\n`;
description += `\n_This bug report was drafted by the Smart Bug Assistant and reviewed by a human before creation._`;

return [{
  json: {
    title: bug.title,
    description,
    stepsToReproduce: bug.stepsToReproduce,
    expectedResult: bug.expectedResult,
    actualResult: bug.actualResult,
    severity: bug.severity,
    severityJustification: bug.severityJustification,
    likelyDuplicate: bug.likelyDuplicate,
    duplicateCandidateKey: bug.duplicateCandidateKey,
    duplicateReason: bug.duplicateReason,
    duplicateCandidatesText: dupCtx.duplicateCandidatesText,
    storyKey,
    revisionCount,
    maxRevisions
  }
}];

const form = $input.item.json;

const revisionCount = Number(form['Revision Count']) || 0;
const maxRevisions = Number(form['Max Revisions']) || 3;
const comment = (form['Revision Comments'] || '').toString().trim();
const hasComment = comment.length > 0;
const canRevise = form.Decision === 'Rejected' && hasComment && revisionCount < maxRevisions;

return [{
  json: {
    ...form,
    revisionCount,
    maxRevisions,
    hasComment,
    canRevise
  }
}];

const data = $input.item.json;
const storyKey = data['Related Story'];

let description = `*Steps to Reproduce:*\n${data['Steps to Reproduce']}\n\n`;
description += `*Expected Result:*\n${data['Expected Result']}\n\n`;
description += `*Actual Result:*\n${data['Actual Result']}\n\n`;
description += `*Severity:* ${data['Severity']}\n\n`;
if (storyKey) description += `*Related Story:* ${storyKey}\n`;
description += `\n_This bug report was drafted by the Smart Bug Assistant, revised ${data.revisionCount || 0} time(s), and approved by a human before creation._`;

return [{
  json: {
    title: data['Bug Title'],
    description,
    severity: data['Severity'],
    storyKey,
    revisionCount: data.revisionCount || 0
  }
}];

const created = $input.item.json;
const finalBug = $('Finalize Approved Bug').item.json;

const bugKey = created.key || created.id || 'UNKNOWN';

let md = `**Decision:** Approved\n\n**New Bug Created:** ${bugKey}\n\n`;
md += `**Title:** ${finalBug.title}\n\n`;
md += `**Severity:** ${finalBug.severity}\n\n`;
if (finalBug.storyKey) md += `**Related Story:** ${finalBug.storyKey}\n\n`;
md += `**Revisions before approval:** ${finalBug.revisionCount}\n\n`;
md += `${finalBug.description}`;

return [{ json: { output: md, decision: 'Approved', bugKey, storyKey: finalBug.storyKey, revisionCount: finalBug.revisionCount } }];

const data = $input.item.json;
const dupKey = (data['Duplicate Issue Key (fill in / confirm if marking as duplicate)'] || '').trim();

let comment = `*Possible Duplicate Reported*

`;
comment += `A tester reported a bug that a human reviewer judged as a likely duplicate of this issue.

`;
comment += `*Drafted Title:* ${data['Bug Title']}

`;
comment += `*Steps to Reproduce:*
${data['Steps to Reproduce']}

`;
comment += `*Expected Result:*
${data['Expected Result']}

`;
comment += `*Actual Result:*
${data['Actual Result']}

`;
comment += `*Severity:* ${data['Severity']}

`;
if (data['Related Story']) comment += `*Related Story:* ${data['Related Story']}

`;
comment += `_No new bug was created - this was linked as a duplicate by a human reviewer via the Smart Bug Assistant._`;

return [{ json: { duplicateIssueKey: dupKey, commentBody: comment, originalTitle: data['Bug Title'] } }];

const prep = $('Prepare Duplicate Link Comment').item.json;

let md = `**Decision:** Marked as Duplicate\n\n`;
md += `**Linked to Existing Bug:** ${prep.duplicateIssueKey}\n\n`;
md += `**Drafted Title (not created):** ${prep.originalTitle}\n\n`;
md += `_A comment referencing this report was added to ${prep.duplicateIssueKey} instead of creating a new bug._`;

return [{ json: { output: md, decision: 'Marked as Duplicate', duplicateIssueKey: prep.duplicateIssueKey } }];

const form = $input.item.json;
const dupCtx = $('Format Duplicate Candidates').first().json;

const newRevisionCount = (form.revisionCount || 0) + 1;

return [{
  json: {
    ...dupCtx,
    isRevision: true,
    revisionComments: form['Revision Comments'],
    previousDraft: {
      title: form['Bug Title'],
      stepsToReproduce: form['Steps to Reproduce'],
      expectedResult: form['Expected Result'],
      actualResult: form['Actual Result'],
      severity: form['Severity']
    },
    revisionCount: newRevisionCount
  }
}];

const data = $input.item.json;

let md = `**Decision:** Rejected\n\n`;

if (data.revisionCount >= data.maxRevisions) {
  md += `Maximum revision attempts (${data.maxRevisions}) reached without approval. This bug report needs manual handling outside this workflow.\n\n`;
} else if (!data.hasComment) {
  md += `The drafted bug report was rejected with no revision comments, so it was not sent back for AI revision. No issue was created in Jira.\n\n`;
}

md += `**Last Drafted Title:** ${data['Bug Title']}\n\n`;
md += `**Last Drafted Severity:** ${data['Severity']}\n\n`;
if (data['Related Story']) md += `**Related Story:** ${data['Related Story']}\n\n`;
md += `**Revisions used:** ${data.revisionCount} of ${data.maxRevisions}\n\n`;
md += `_To try again, start a new run with a corrected or more detailed bug description._`;

return [{ json: { output: md, decision: 'Rejected', revisionCount: data.revisionCount } }];
